    oa:
      'M18.75 6.75V5q0-.725-.513-1.237A1.69 1.69 0 0 0 17 3.25H7q-.725 0-1.237.513A1.69 1.69 0 0 0 5.25 5v13q0 .725.513 1.237.512.513 1.237.513h.75a.75.75 0 0 1 0 1.5H7a3.13 3.13 0 0 1-2.298-.952A3.13 3.13 0 0 1 3.75 18v-2.25H2.5a.75.75 0 0 1 0-1.5h1.25v-5.5H2.5a.75.75 0 0 1 0-1.5h1.25V5q0-1.346.952-2.298A3.13 3.13 0 0 1 7 1.75h10q1.345 0 2.298.952.952.951.952 2.298v1.75a.75.75 0 0 1-1.5 0m-12 9.75v-10a.75.75 0 0 1 1.5 0v10a.75.75 0 0 1-1.5 0m3.875-4.875a4.875 4.875 0 1 1 9.75 0 4.875 4.875 0 0 1-9.75 0M12.878 9.5h.016a1.269 1.269 0 0 1 .92 2.143c-.336.38-.539.753-.553 1.285-.018.649.498 1.301.993 1.576.494.276 1.088.442 1.961.317.34-.048.699-.15 1.046-.315A3.375 3.375 0 1 0 12.878 9.5m7.956 12.312a5.9 5.9 0 0 0-2.171-2.348q-1.449-.9-3.163-.9t-3.163.9a5.9 5.9 0 0 0-2.17 2.348.75.75 0 0 1-1.333-.689 7.4 7.4 0 0 1 2.711-2.933 7.35 7.35 0 0 1 3.955-1.127q2.143 0 3.954 1.127a7.4 7.4 0 0 1 2.712 2.933.752.752 0 0 1-.666 1.094.75.75 0 0 1-.666-.405',
